<template><main class="community-page"><section class="community-hero"><div class="page-shell"><p class="eyebrow">CUSTOMER SUPPORT</p><h1>공지사항</h1><p>카리나벨의 새로운 소식과 중요한 안내를 전합니다.</p></div></section><div class="community-shell page-shell"><div class="community-toolbar"><p>전체 <strong>{{noticeList.length}}</strong>건</p><label><i class="fa-solid fa-magnifying-glass"></i><input v-model.trim="keyword" type="search" placeholder="공지사항 검색" /></label></div><div v-if="isLoading" class="community-loading"><span></span><p>공지사항을 불러오고 있습니다.</p></div><div v-else-if="loadError" class="community-empty"><i class="fa-solid fa-circle-exclamation"></i><h2>공지사항을 불러오지 못했습니다.</h2><button @click="fetchNotices">다시 시도</button></div><ol v-else-if="filteredNotices.length" class="notice-list"><li v-for="(notice,index) in filteredNotices" :key="notice._id" @click="goToDetail(notice._id)"><span class="notice-number">{{String((currentPage-1)*pageSize+index+1).padStart(2,'0')}}</span><div><span v-if="index===0&&currentPage===1" class="notice-badge">NEW</span><h2>{{notice.title}}</h2><p>{{notice.summary||truncate(notice.content)}}</p></div><time>{{formatDate(notice.date||notice.createdAt)}}</time><i class="fa-solid fa-arrow-right"></i></li></ol><div v-else class="community-empty"><i class="fa-regular fa-file-lines"></i><h2>{{keyword?'검색 결과가 없습니다.':'등록된 공지사항이 없습니다.'}}</h2><p>다른 검색어를 입력해 보세요.</p></div><Pagination v-if="!keyword&&totalPages>1" :current-page="currentPage" :total-pages="totalPages" @page-change="handlePageChange" /></div></main></template>
<script setup>import{computed,onMounted,ref}from"vue";import{useRouter}from"vue-router";import NoticeService from"@/api/NoticeService";import Pagination from"@/components/common/Pagination.vue";const router=useRouter(),noticeList=ref([]),currentPage=ref(1),totalPages=ref(1),keyword=ref(""),isLoading=ref(true),loadError=ref(false),pageSize=8;const filteredNotices=computed(()=>{if(!keyword.value)return noticeList.value;const key=keyword.value.toLowerCase();return noticeList.value.filter(item=>`${item.title||''} ${item.summary||''} ${item.content||''}`.toLowerCase().includes(key))});const fetchNotices=async()=>{isLoading.value=true;loadError.value=false;try{const response=await NoticeService.getNoticeList({page:currentPage.value-1,size:pageSize},localStorage.getItem("token"));noticeList.value=response.data.notices||[];totalPages.value=Math.max(1,Math.ceil(Number(response.data.total||0)/pageSize))}catch(error){console.error(error);noticeList.value=[];loadError.value=true}finally{isLoading.value=false}};const formatDate=value=>value?new Date(value).toLocaleDateString("ko-KR",{year:"numeric",month:"2-digit",day:"2-digit"}).replace(/\. /g,".").replace(/\.$/,""):"-";const truncate=value=>value&&value.length>90?`${value.slice(0,90)}…`:value||"";const goToDetail=id=>router.push(`/notice/${id}`);const handlePageChange=page=>{currentPage.value=page;fetchNotices()};onMounted(fetchNotices);</script>
<style>.community-page{background:#fff}.community-hero{padding:82px 0;text-align:center;background:var(--color-warm)}.community-hero h1{margin:10px 0 7px;font-family:Georgia,"Noto Serif KR",serif;font-size:clamp(2.5rem,4.2vw,3.8rem);font-weight:400}.community-hero>div>p:last-child{color:#8c8287;font-size:.78rem}.community-shell{padding-block:65px 110px}.community-toolbar{display:flex;align-items:center;justify-content:space-between;padding-bottom:18px;border-bottom:1px solid #322c2f;color:#867c81;font-size:.7rem}.community-toolbar strong{color:var(--color-brand)}.community-toolbar label{width:230px;display:flex;align-items:center;gap:8px;padding:8px 4px;border-bottom:1px solid #bdb3b7}.community-toolbar input{width:100%;border:0;outline:0;background:transparent;font-size:.72rem}.notice-list li{display:grid;grid-template-columns:50px 1fr 100px 25px;align-items:center;gap:20px;padding:25px 10px;border-bottom:1px solid var(--color-line);cursor:pointer;transition:.2s}.notice-list li:hover{padding-inline:18px;background:#fbf8f6}.notice-number{color:#b2a8ad;font-family:Georgia,serif;font-size:.8rem}.notice-list h2{display:inline;font-size:.88rem;font-weight:600}.notice-list p{margin-top:5px;color:#968c91;font-size:.68rem}.notice-list time{color:#a59ba0;font-size:.65rem}.notice-list li>i{color:#a99fa4;font-size:.7rem}.notice-badge{margin-right:8px;padding:3px 5px;color:#fff;background:var(--color-accent);font-size:.5rem}.community-empty,.community-loading{padding:100px 20px;text-align:center}.community-empty>i{color:#b99aa2;font-size:2rem}.community-empty h2{margin:15px 0 5px;font-size:1rem}.community-empty p,.community-loading p{color:#9d9398;font-size:.72rem}.community-empty button{margin-top:20px;padding:10px 17px;border:1px solid var(--color-brand);color:var(--color-brand);background:#fff}.community-loading span{display:block;width:30px;height:30px;margin:0 auto 12px;border:2px solid #e5dcdf;border-top-color:var(--color-brand);border-radius:50%;animation:auth-spin .8s linear infinite}@media(max-width:600px){.community-hero{padding:60px 0}.community-shell{padding-block:40px 80px}.community-toolbar{align-items:flex-start;flex-direction:column;gap:15px}.community-toolbar label{width:100%}.notice-list li{grid-template-columns:32px 1fr 15px;gap:10px;padding-block:20px}.notice-list time{grid-column:2}.notice-list p{display:none}}
</style>
